def main():
    assert len(IDS) == 60, len(IDS)
    assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()), set(P.keys()) - set(IDS))
    os.makedirs(OUT, exist_ok=True)
    sizes = {}
    for cid in IDS:
        rec = P[cid]
        obj = {
            "case_id": cid,
            "prediction_text": rec["prediction_text"],
            "basis": rec["basis"],
            "confidence": rec["confidence"],
            "trigger": rec["trigger"],
        }
        assert set(obj.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
        trg = obj["trigger"]
        assert set(trg.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
        assert all(isinstance(trg[k], bool) for k in ("changed_main", "reserve_used", "disputed"))
        assert isinstance(trg["reason"], str)
        assert 0.0 <= obj["confidence"] <= 1.0
        path = os.path.join(OUT, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=1)
        # per-file readback validation
        with open(path, encoding="utf-8") as f:
            back = json.load(f)
        assert back["case_id"] == cid and back["prediction_text"] == obj["prediction_text"]
        sizes[cid] = os.path.getsize(path)
    cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
    ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
    di = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
    print(f"WROTE {len(sizes)} files")
    print(f"trigger counts: changed_main={cm} reserve_used={ru} disputed={di}")
    for cid in IDS:
        print(cid, sizes[cid])

if __name__ == "__main__":
    main()
